import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"關於","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/about.md","filePath":"zh-HK/user-guide/settings/about.md","lastUpdated":1785993908000}'),s={name:"zh-HK/user-guide/settings/about.md"};function n(i,e,l,u,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="關於" tabindex="-1">關於 <a class="header-anchor" href="#關於" aria-label="Permalink to &quot;關於&quot;">​</a></h1><p>顯示 App、Core、Service、CLI 四個組件的版本號(顏色會反映服務當前是否健康)、Lertaro 的簡短說明，以及項目主頁和在線使用手冊的鏈接。</p><h2 id="配置資料夾" tabindex="-1">配置資料夾 <a class="header-anchor" href="#配置資料夾" aria-label="Permalink to &quot;配置資料夾&quot;">​</a></h2><p>緊接着下方還有兩個鏈接，用來打開 Lertaro 讀寫自身配置的資料夾——鏈接文字本身就是實際路徑，點擊時如果資料夾還不存在會先創建出來:</p><ul><li><strong>使用者配置資料夾</strong> —— 存放 <code>user-settings.json</code> 的每使用者資料夾。每次保存設定時，都會先把當前檔案輪轉備份為 <code>user-settings.json.bak.1</code>(舊的備份依次往後順延，最多保留到 <code>.bak.5</code>)，再寫入新檔案，所以一次誤改或者保存過程中崩潰，總能找到一份最近的備份恢復。</li><li><strong>系統配置資料夾</strong> —— 後臺服務使用的共享、機器級資料夾(<code>machine-settings.json</code>、索引快取，以及伺服器端日誌)。</li></ul><h2 id="檢查更新" tabindex="-1">檢查更新 <a class="header-anchor" href="#檢查更新" aria-label="Permalink to &quot;檢查更新&quot;">​</a></h2><ul><li><strong>檢查更新</strong> 按鈕 —— 查詢是否有新版本;按鈕文字本身會反映進度(&quot;正在檢查更新...&quot;，之後顯示 &quot;已是最新版本&quot;或找到的新版本號)。</li><li>如果非系統管理員帳戶無法停止後臺服務來原地安裝更新，會顯示一條警告橫幅，並引導你前往手動下載頁面。</li><li>一旦發現新版本: <ul><li><strong>靜默自動更新</strong> —— 後臺下載安裝，顯示進度條，完成後自動重啓 Lertaro。</li><li><strong>前往下載頁面</strong> —— 在瀏覽器中打開 GitHub release 頁面，手動安裝。</li></ul></li></ul><p>這個頁面和<a href="./general.html#系統">通用 → 系統</a>裏的<strong>啓動時自動檢查更新</strong> / <strong>自動靜默更新</strong>兩個核取方塊是配套的——那兩項控制是否在啓動時自動執行這次檢查;這個頁面則是讓你隨時手動觸發一次。</p>',8)])])}const _=t(s,[["render",n]]);export{h as __pageData,_ as default};
